   276→    /**
   277→     * Extraer mensaje de error de una excepción de request.
   278→     *
   279→     * @param RequestException $error Excepción de la petición.
   280→     * @return string Mensaje de error.
   281→     * @author Esperanza Olivo
   282→     */
   283→    protected function extraerMensajeError(RequestException $error): string
   284→    {
   285→        if ($error->hasResponse()) {
   286→            $respuesta_error = json_decode($error->getResponse()->getBody()->getContents(), true);
   287→            return $respuesta_error['message'] ?? $respuesta_error['error'] ?? $error->getMessage();
   288→        }
   289→
   290→        return $error->getMessage();
   291→    }
