   293→    /**
   294→     * Limpiar y formatear número de teléfono.
   295→     *
   296→     * @param string $telefono Número de teléfono.
   297→     * @return string Número formateado.
   298→     * @author Esperanza Olivo
   299→     */
   300→    protected function limpiarNumeroTelefono(string $telefono): string
   301→    {
   302→        $telefono = preg_replace('/[\s\-\(\)\+]/', '', $telefono);
   303→
   304→        if (!str_starts_with($telefono, '57') && strlen($telefono) === 10) {
   305→            $telefono = '57' . $telefono;
   306→        }
   307→
   308→        return $telefono;
   309→    }
