   311→    /**
   312→     * Manejar errores de la API.
   313→     *
   314→     * @param RequestException $error Excepción de la petición.
   315→     * @param string $operacion Descripción de la operación.
   316→     * @throws Exception
   317→     * @author Esperanza Olivo
   318→     */
   319→    protected function manejarError(RequestException $error, string $operacion): void
   320→    {
   321→        $mensaje_error = "Error al {$operacion}";
   322→
   323→        if ($error->hasResponse()) {
   324→            $respuesta_error = json_decode($error->getResponse()->getBody()->getContents(), true);
   325→            $mensaje_error   = $respuesta_error['message'] ?? $respuesta_error['error'] ?? $mensaje_error;
   326→        }
   327→
   328→        Log::error("WhatsApp API: Error al {$operacion}", [
   329→            'error'   => $mensaje_error,
   330→            'codigo'  => $error->getCode(),
   331→            'mensaje' => $error->getMessage()
   332→        ]);
   333→
   334→        throw new Exception($mensaje_error);
   335→    }
