   337→    /**
   338→     * Reenviar notificaciones de WhatsApp fallidas.
   339→     *
   340→     * @param int $vacante_id ID de la vacante.
   341→     * @param array $candidatos Lista de candidatos a reenviar.
   342→     * @return array Resultado con estadísticas de envío.
   343→     * @author Esperanza Olivo
   344→     */
   345→    public function reenviarNotificaciones(int $vacante_id, array $candidatos): array
   346→    {
   347→        $vacante_repositorio = app(\App\Http\Repositories\Vacantes\VacanteRepository::class);
   348→        $token_servicio = app(\App\Http\Services\Usuarios\TokenAccesoService::class);
   349→        $etapa_vacante_usuario_repositorio = app(\App\Http\Repositories\Vacantes\EtapaVacanteUsuarioRepository::class);
   350→
   351→        $vacante = $vacante_repositorio->getUno($vacante_id);
   352→        $empresa = $vacante->empresa;
   353→
   354→        // Buscar plantilla automáticamente por nombre
   355→        $plantilla_id = $this->obtenerIdPlantillaPorNombre('invitacion_etapa_1');
   356→
   357→        if (!$plantilla_id) {
   358→            return [
   359→                'total_candidatos'          => count($candidatos),
   360→                'candidatos_procesados'     => 0,
   361→                'notificaciones_enviadas'   => 0,
   362→                'notificaciones_fallidas'   => count($candidatos),
   363→                'canal_comunicacion'        => 'whatsapp',
   364→                'error'                     => 'No se encontró la plantilla de WhatsApp "invitacion_etapa_1"',
   365→                'detalles_notificaciones'   => []
   366→            ];
   367→        }
   368→
   369→        $resultado = [
   370→            'total_candidatos'          => count($candidatos),
   371→            'candidatos_procesados'     => 0,
   372→            'notificaciones_enviadas'   => 0,
   373→            'notificaciones_fallidas'   => 0,
   374→            'canal_comunicacion'        => 'whatsapp',
   375→            'detalles_notificaciones'   => []
   376→        ];
   377→
   378→        foreach ($candidatos as $candidato) {
   379→            
   380→            $etapa_vacante_usuario_id = $candidato['etapa_vacante_usuario_id'];
   381→            $usuario_vacante = $etapa_vacante_usuario_repositorio->getUno($etapa_vacante_usuario_id);
   382→            $etapa = $vacante->etapas()->where('activa', true)->orderBy('orden')->first();
   383→
   384→            $plantilla_nombre = match($etapa->nombre) {
   385→                'Contratados' => 'notificacion_contratado',
   386→                'Descartados' => 'descartado',
   387→                default => 'invitacion_etapa_1'
   388→            };
   389→
   390→            $plantilla_id = $this->obtenerIdPlantillaPorNombre($plantilla_nombre);
   391→
   392→             if (!$plantilla_id) {
   393→                $resultado['notificaciones_fallidas']++;
   394→                $resultado['detalles_notificaciones'][] = [
   395→                    'exito'                    => false,
   396→                    'etapa_vacante_usuario_id' => $etapa_vacante_usuario_id,
   397→                    'nombre'                   => $nombre_candidato,
   398→                    'error'                    => "No se encontró la plantilla '{$plantilla_nombre}'"
   399→                ];
   400→                continue;
   401→            }
   402→
   403→            $usuario = $usuario_vacante->usuario;
   404→            $nombre_candidato = trim($usuario->nombres . ' ' . $usuario->apellidos) ?: 'Candidato';
   405→            $telefono = $candidato['telefono'] ?? $usuario->telefono;
   406→
   407→            if (empty($telefono)) {
   408→                $resultado['notificaciones_fallidas']++;
   409→                $resultado['detalles_notificaciones'][] = [
   410→                    'exito'                    => false,
   411→                    'etapa_vacante_usuario_id' => $etapa_vacante_usuario_id,
   412→                    'usuario_id'               => $usuario->id,
   413→                    'nombre'                   => $nombre_candidato,
   414→                    'telefono'                 => null,
   415→                    'error'                    => 'El candidato no tiene número de teléfono'
   416→                ];
   417→                continue;
   418→            }
   419→
   420→            $token_acceso = $token_servicio->generar($usuario->id);
   421→            $enlace = request()->getSchemeAndHttpHost() . "/control-acceso/{$token_acceso->token}?vacante_id={$vacante->id}";
   422→
   423→            if ($etapa->nombre === 'Contratados') {
   424→                $variables = [
   425→                    $nombre_candidato,
   426→                    $empresa->nombre_comercial ?? $empresa->razon_social ?? 'La empresa',
   427→                    $vacante->nombre_vacante ?? 'la vacante'
   428→                ];
   429→            } elseif ($etapa->nombre === 'Descartados') {
   430→                $variables = [];
   431→            } else {
   432→                $variables = [
   433→                    $nombre_candidato,
   434→                    $empresa->nombre_comercial ?? $empresa->razon_social ?? 'La empresa',
   435→                    $vacante->nombre_vacante ?? 'la vacante',
   436→                    $etapa->nombre ?? 'la etapa',
   437→                    now()->addDays(7)->format('d/m/Y'),
   438→                    $enlace
   439→                ];
   440→            }
   441→
   442→
   443→            try {
   444→                $resultado_envio = $this->enviarMensajePlantilla(
   445→                    $plantilla_id,
   446→                    $telefono,
   447→                    $variables,
   448→                    null,
   449→                    [],
   450→                    [],
   451→                    [
   452→                        'vacante_id'               => $vacante->id,
   453→                        'etapa_vacante_usuario_id' => $usuario_vacante?->id,
   454→                        'tipo'                     => 'reintento',
   455→                        'metadata'                 => [
   456→                            'etapa_id'     => $etapa->id ?? null,
   457→                            'etapa_nombre' => $etapa->nombre ?? null,
   458→                            'empresa_id'   => $empresa->id
   459→                        ]
   460→                    ]
   461→                );
   462→
   463→                $resultado['candidatos_procesados']++;
   464→
   465→                if ($resultado_envio['exito'] ?? false) {
   466→                    $resultado['notificaciones_enviadas']++;
   467→                    $resultado['detalles_notificaciones'][] = [
   468→                        'exito'                    => true,
   469→                        'etapa_vacante_usuario_id' => $etapa_vacante_usuario_id,
   470→                        'usuario_id'               => $usuario->id,
   471→                        'nombre'                   => $nombre_candidato,
   472→                        'telefono'                 => $telefono,
   473→                        'mensaje_id'               => $resultado_envio['mensaje_id'] ?? null,
   474→                        'notificacion_id'          => $resultado_envio['notificacion_id'] ?? null
   475→                    ];
   476→                } else {
   477→                    $resultado['notificaciones_fallidas']++;
   478→                    $resultado['detalles_notificaciones'][] = [
   479→                        'exito'                    => false,
   480→                        'etapa_vacante_usuario_id' => $etapa_vacante_usuario_id,
   481→                        'usuario_id'               => $usuario->id,
   482→                        'nombre'                   => $nombre_candidato,
   483→                        'telefono'                 => $telefono,
   484→                        'error'                    => $resultado_envio['error'] ?? 'Error al enviar'
   485→                    ];
   486→                }
   487→            } catch (Exception $e) {
   488→                $resultado['notificaciones_fallidas']++;
   489→                $resultado['detalles_notificaciones'][] = [
   490→                    'exito'                    => false,
   491→                    'etapa_vacante_usuario_id' => $etapa_vacante_usuario_id,
   492→                    'usuario_id'               => $usuario->id,
   493→                    'nombre'                   => $nombre_candidato,
   494→                    'telefono'                 => $telefono,
   495→                    'error'                    => $e->getMessage()
   496→                ];
   497→            }
   498→        }
   499→
   500→        return $resultado;
   501→    }
