   503→    /**
   504→     * Obtener notificaciones fallidas o pendientes de una vacante agrupadas por usuario.
   505→     *
   506→     * @param int $vacante_id ID de la vacante.
   507→     * @return array Lista de usuarios con notificaciones fallidas o pendientes.
   508→     * @author Esperanza Olivo
   509→     */
   510→    public function obtenerNotificacionesFallidas(int $vacante_id): array
   511→    {
   512→        $notificaciones = NotificacionWhatsApp::where('vacante_id', $vacante_id)
   513→            ->whereIn('estado', [NotificacionWhatsApp::ESTADO_FALLIDO, NotificacionWhatsApp::ESTADO_PENDIENTE])
   514→            ->whereNotNull('etapa_vacante_usuario_id')
   515→            ->with(['etapaVacanteUsuario' => function ($query) {
   516→                $query->with('usuario:id,nombres,apellidos,telefono');
   517→            }])
   518→            ->orderBy('created_at', 'desc')
   519→            ->get()
   520→            ->groupBy('etapa_vacante_usuario_id');
   521→
   522→        $resultado = [];
   523→
   524→        foreach ($notificaciones as $etapa_vacante_usuario_id => $notifs) {
   525→            $ultima = $notifs->first();
   526→            $usuario = $ultima->etapaVacanteUsuario?->usuario;
   527→
   528→            $resultado[] = [
   529→                'etapa_vacante_usuario_id' => $etapa_vacante_usuario_id,
   530→                'nombre'                   => $usuario ? trim($usuario->nombres . ' ' . $usuario->apellidos) : 'Desconocido',
   531→                'telefono'                 => $ultima->telefono,
   532→                'ultimo_error'             => $ultima->error_mensaje,
   533→                'ultimo_intento'           => $ultima->created_at->format('d/m/Y H:i'),
   534→                'intentos'                 => $notifs->count(),
   535→                'notificacion_id'          => $ultima->id
   536→            ];
   537→        }
   538→
   539→        return $resultado;
