   559→
   560→        if (!$vacante || !$usuario_vacante || !$usuario_vacante->usuario) {
   561→            return [
   562→                'exito' => false,
   563→                'error' => 'Vacante o candidato no encontrado'
   564→            ];
   565→        }
   566→
   567→        $usuario = $usuario_vacante->usuario;
   568→        $empresa = $vacante->empresa;
   569→
   570→        $etapa = $usuario_vacante->etapa;
   571→
   572→        $plantilla_nombre = match($etapa->nombre) {
   573→            EtapaVacante::CONTRATADOS_NOMBRE => 'notificacion_contratado',
   574→            EtapaVacante::DESCARTADOS_NOMBRE => 'descartado',
   575→            default => 'invitacion_etapa_1'
   576→        };
   577→
   578→        $plantilla_whatsapp_id = $this->obtenerIdPlantillaPorNombre($plantilla_nombre);
   579→
   580→        if (!$plantilla_whatsapp_id) {
   581→            return [
   582→                'exito' => false,
   583→                'error' => "No se encontró la plantilla de WhatsApp '{$plantilla_nombre}'"
   584→            ];
   585→        }
   586→
   587→        $nombre_candidato = trim($usuario->nombres . ' ' . $usuario->apellidos) ?: 'Candidato';
   588→        $token_acceso = $token_servicio->generar($usuario->id);
   589→        $enlace = request()->getSchemeAndHttpHost() . "/control-acceso/{$token_acceso->token}?vacante_id={$vacante->id}";
   590→
   591→        $nombre_empresa = $empresa->nombre_comercial ?? $empresa->razon_social ?? 'La empresa';
   592→        $nombre_vacante = $vacante->nombre_vacante ?? 'la vacante';
   593→
   594→        if ($etapa->nombre === EtapaVacante::CONTRATADOS_NOMBRE) {
   595→            $variables = [
   596→                $nombre_candidato,
   597→                $nombre_empresa,
   598→                $nombre_vacante
   599→            ];
   600→        } elseif ($etapa->nombre === EtapaVacante::DESCARTADOS_NOMBRE) {
   601→            $variables = [];
   602→        } else {
   603→
   604→            $variables = [
   605→                $nombre_candidato,
   606→                $nombre_empresa,
   607→                $nombre_vacante,
   608→                $etapa->nombre ?? 'la etapa',
   609→                Carbon::now()->addDays(7)->format('d/m/Y'),
   610→                $enlace
   611→            ];
   612→        }
   613→
   614→        try {
   615→            $resultado_envio = $this->enviarMensajePlantilla(
   616→                $plantilla_whatsapp_id,
